export const listInviteSuggestionsQuery = `-- name: ListInviteSuggestions :many
SELECT u.id, u.name, u.email::text AS email, false::boolean AS pending
FROM "exagram"."users" u
WHERE "exagram".live_member(u.id, $1::uuid)
  AND u.id <> $2::uuid
  AND u.id IS DISTINCT FROM (
    CASE
      WHEN $3::uuid IS NOT NULL THEN "exagram".artifact_owner($3::uuid)
      ELSE (SELECT p.owner_id FROM "exagram"."projects" p WHERE p.id = $4::uuid)
    END
  )
  AND (
    $3::uuid IS NULL
    OR NOT "exagram".reaches_artifact(u.id, $3::uuid)
  )
  AND NOT EXISTS (
    SELECT 1
    FROM "exagram"."grants" g
    JOIN "exagram"."projects" p ON p.id = $4::uuid
    WHERE g.grantee_id = u.id AND g.project_id IN (p.id, p.parent_project_id)
  )
  AND (
    $5::text IS NULL
    OR u.name ILIKE '%' || $5::text || '%'
    OR u.email::text ILIKE '%' || $5::text || '%'
  )
ORDER BY u.name, u.email
LIMIT $6::int`

