export const hasPinnedGrantUnderProjectQuery = `-- name: HasPinnedGrantUnderProject :one
SELECT EXISTS (
  SELECT 1
  FROM "exagram"."grants" g
  JOIN "exagram"."artifacts" a ON a.id = g.artifact_id
  WHERE g.grantee_id = $1::uuid
    AND g.pinned_revision_id IS NOT NULL
    AND a.deleted_at IS NULL
    AND (
      a.project_id = $2::uuid
      OR a.project_id IN (SELECT cp.id FROM "exagram"."projects" cp WHERE cp.parent_project_id = $2::uuid)
    )
) AS pinned`

export interface HasPinnedGrantUnderProjectArgs {
	userId: string
	projectId: string
}

export interface HasPinnedGrantUnderProjectRow {
	pinned: string
}

export async function hasPinnedGrantUnderProject(
	sql: Sql,
	args: HasPinnedGrantUnderProjectArgs,
): Promise<HasPinnedGrantUnderProjectRow | null> {
	const rows = await sql.unsafe(hasPinnedGrantUnderProjectQuery, [args.userId, args.projectId]).values()
	if (rows.length !== 1) {
		return null
	}
	const row = rows[0]
	if (!row) {
		return null
	}
	return {
		pinned: row[0],
	}
}

export const countInvitedMembersBySenderSinceQuery = `-- name: CountInvitedMembersBySenderSince :one
SELECT count(*)::int AS total
FROM "exagram"."ledger_calls" c
WHERE c.principal_kind = 'user'
  AND c.principal_id = $1::uuid
  AND c.action IN ('workspace.invite.create', 'grant.share_by_email')
  AND c.started_at >= $2::timestamptz`

export interface CountInvitedMembersBySenderSinceArgs {
	senderId: string
	since: Date
}

export interface CountInvitedMembersBySenderSinceRow {
	total: number
}

export async function countInvitedMembersBySenderSince(
	sql: Sql,
	args: CountInvitedMembersBySenderSinceArgs,
): Promise<CountInvitedMembersBySenderSinceRow | null> {
	const rows = await sql.unsafe(countInvitedMembersBySenderSinceQuery, [args.senderId, args.since]).values()
	if (rows.length !== 1) {
		return null
	}
	const row = rows[0]
	if (!row) {
		return null
	}
	return {
		total: row[0],
	}
}

export const lockInviteKeyQuery = `-- name: LockInviteKey :exec
SELECT pg_advisory_xact_lock(hashtext($1::text))`

export interface LockInviteKeyArgs {
	lockKey: string
}

export interface LockInviteKeyRow {
	pgAdvisoryXactLock: string
}

export async function lockInviteKey(sql: Sql, args: LockInviteKeyArgs): Promise<void> {
	await sql.unsafe(lockInviteKeyQuery, [args.lockKey])
}

export const lockOrphanInvitedMembersQuery = `-- name: LockOrphanInvitedMembers :many
WITH orphans AS (
	SELECT u.id FROM "exagram"."users" u
	WHERE u.invited_at IS NOT NULL
	  AND u.invited_at < $1::timestamptz
	  AND NOT EXISTS (SELECT 1 FROM "exagram"."grants" g WHERE g.grantee_id = u.id)
	  AND NOT EXISTS (SELECT 1 FROM "exagram"."user_identities" i WHERE i.user_id = u.id)
), locked AS (
	SELECT m.user_id FROM "exagram"."memberships" m
	WHERE m.user_id IN (SELECT id FROM orphans)
	ORDER BY m.user_id, m.workspace_id
	FOR NO KEY UPDATE SKIP LOCKED
), locked_counts AS (
	SELECT user_id, count(*) AS n FROM locked GROUP BY user_id
), held_counts AS (
	SELECT m.user_id, count(*) AS n FROM "exagram"."memberships" m
	WHERE m.user_id IN (SELECT id FROM orphans)
	GROUP BY m.user_id
), bare_candidates AS MATERIALIZED (
	SELECT u.id, u.email FROM "exagram"."users" u
	WHERE u.id IN (SELECT id FROM orphans)
	  AND NOT EXISTS (SELECT 1 FROM "exagram"."memberships" m WHERE m.user_id = u.id)
), bare AS (
	SELECT c.id FROM bare_candidates c
	WHERE pg_try_advisory_xact_lock(hashtext('bare:' || lower(c.email::text)))
)
SELECT u.id, COALESCE(lc.n, 0)::int AS memberships
FROM "exagram"."users" u
LEFT JOIN locked_counts lc ON lc.user_id = u.id
LEFT JOIN held_counts hc ON hc.user_id = u.id
WHERE u.id IN (SELECT id FROM orphans)
  AND (
    EXISTS (SELECT 1 FROM bare b WHERE b.id = u.id)
    OR (lc.n IS NOT NULL AND lc.n = hc.n)
  )
FOR UPDATE OF u SKIP LOCKED`

export interface LockOrphanInvitedMembersArgs {
	before: Date
}

export interface LockOrphanInvitedMembersRow {
	id: string
	memberships: number
}

export async function lockOrphanInvitedMembers(
	sql: Sql,
	args: LockOrphanInvitedMembersArgs,
): Promise<LockOrphanInvitedMembersRow[]> {
	return (await sql.unsafe(lockOrphanInvitedMembersQuery, [args.before]).values()).map((row) => ({
		id: row[0],
		memberships: row[1],
	}))
}

export const deleteLockedOrphanInvitedMembersQuery = `-- name: DeleteLockedOrphanInvitedMembers :many
DELETE FROM "exagram"."users" u
USING unnest($1::uuid[], $2::int[]) AS l(id, memberships)
WHERE u.id = l.id
  AND u.invited_at IS NOT NULL
  AND u.invited_at < $3::timestamptz
  AND NOT EXISTS (SELECT 1 FROM "exagram"."grants" g WHERE g.grantee_id = u.id)
  AND NOT EXISTS (SELECT 1 FROM "exagram"."user_identities" i WHERE i.user_id = u.id)
  AND (SELECT count(*) FROM "exagram"."memberships" m WHERE m.user_id = u.id) = l.memberships
RETURNING u.id`

export interface DeleteLockedOrphanInvitedMembersArgs {
	ids: string[]
	memberships: number[]
	before: Date
}

export interface DeleteLockedOrphanInvitedMembersRow {
	id: string
}

export async function deleteLockedOrphanInvitedMembers(
	sql: Sql,
	args: DeleteLockedOrphanInvitedMembersArgs,
): Promise<DeleteLockedOrphanInvitedMembersRow[]> {
	return (
		await sql.unsafe(deleteLockedOrphanInvitedMembersQuery, [args.ids, args.memberships, args.before]).values()
	).map((row) => ({
		id: row[0],
	}))
}
